// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// Array initialization: A[i] = (i+2)/n, B[i] = (i+3)/n
void init_array(std::size_t n, auto A, auto B) {
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2))
		           / static_cast<num_t>(n);
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3))
		           / static_cast<num_t>(n);
	});
}

// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, std::size_t n, auto A, auto B) {
	using namespace noarr;

	// Time dimension structure: t = 0 .. tsteps-1
	auto time_struct = scalar<char>() ^ vector<'t'>(tsteps);

	// Spatial slice: i = 1 .. n-2
	auto inner_slice = slice<'i'>(1, n - 2);

#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// First sweep: update B from A
		traverser(A, B).order(inner_slice).for_each([=](auto s) {
			auto left  = neighbor<'i'>(s, -1);
			auto right = neighbor<'i'>(s, +1);

			B[s] = static_cast<num_t>(0.33333) *
			       (A[left] + A[s] + A[right]);
		});

		// Second sweep: update A from B
		traverser(A, B).order(inner_slice).for_each([=](auto s) {
			auto left  = neighbor<'i'>(s, -1);
			auto right = neighbor<'i'>(s, +1);

			A[s] = static_cast<num_t>(0.33333) *
			       (B[left] + B[s] + B[right]);
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// Lengths for the spatial dimension
	auto set_lengths = noarr::set_length<'i'>(n);

	// Allocate data (bags)
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// Initialize arrays
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_jacobi_1d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Optional: print data to stderr to prevent DCE in benchmarking setups
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print elapsed time in seconds
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

