namespace {

constexpr auto i_vec = noarr::vector<'i'>();

struct tuning {
	DEFINE_PROTO_STRUCT(a_layout, i_vec);
	DEFINE_PROTO_STRUCT(b_layout, i_vec);
} tuning;

// initialization function
void init_array(auto A, auto B) {
	using namespace noarr;

	auto n = A | get_length<'i'>();

	traverser(A, B).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		A[state] = ((num_t)i + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i + (num_t)3) / (num_t)n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(std::size_t tsteps, auto A, auto B) {
	using namespace noarr;

	const num_t c = (num_t)0.33333;

	auto n = A | get_length<'i'>();

	// work only on interior points: i = 1 .. n-2
	auto core = noarr::slice<'i'>(1, n - 2);

	// add a (broadcast) time dimension 't' that repeats the 1D sweep tsteps times
	auto trav_t = noarr::traverser(A, B).order(noarr::bcast<'t'>(tsteps));

	#pragma scop
	trav_t.template for_dims<'t'>([=](auto trav_per_t) {
		// restrict to interior points for this time step
		auto trav_core = trav_per_t.order(core);

		// first sweep: update B from A
		trav_core.for_each([=](auto state) {
			auto center = state;
			auto left   = center - noarr::idx<'i'>(1);
			auto right  = center + noarr::idx<'i'>(1);

			B[center] = c * (A[left] + A[center] + A[right]);
		});

		// second sweep: update A from B
		trav_core.for_each([=](auto state) {
			auto center = state;
			auto left   = center - noarr::idx<'i'>(1);
			auto right  = center + noarr::idx<'i'>(1);

			A[center] = c * (B[left] + B[center] + B[right]);
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n      = N;
	std::size_t tsteps = TSTEPS;

	auto set_len = noarr::set_length<'i'>(n);

	// data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_len);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_len);

