[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	auto n = A | get_length<'i'>();

	// Restrict spatial traversal to the interior points i = 1 .. n-2
	auto interior = slice<'i'>(1, n - 2);

	// Time "dimension": just a helper structure to drive the t-loop
	auto t_structure = scalar<char>() ^ vector<'t'>(static_cast<std::size_t>(tsteps));

#pragma scop
	traverser(t_structure).for_each([=](auto /*t_state*/) {
		// First phase: update B from A on interior points
		traverser(A, B).order(interior).for_each([=](auto state) {
			auto left  = A[neighbor<'i'>(state, -1)];
			auto mid   = A[state];
			auto right = A[neighbor<'i'>(state, +1)];

			B[state] = static_cast<num_t>(0.33333) * (left + mid + right);
